    JSArrayBuffer *abuf;
    size_t offset, length;
    JSPiArrayBufferLease result = {0};

    assert(out != NULL);
    memset(out, 0, sizeof(*out));
    if (JS_HasException(ctx))
        return -1;
    buffer = JS_PiGetArrayBufferViewBuffer(ctx, view, &offset, &length, NULL);
    if (JS_IsException(buffer))
